// LinkedIn people search via Unipile, proposed as person entities.
// Executor wraps this body as (async function(args, context){ <code> }); use args
// directly and `return` the result. callProvider(provider, method, path, body?)
// runs the required tool through the dispatcher — pass the tool NAME
// ('unipile_linkedin') and the dispatcher resolves its credentialRef, injects the
// vaulted X-API-KEY, and uses the tool's config.baseUrl = DSN + /api/v1. No
// providerRef arg needed.
const accountId = String(args?.accountId ?? '{{unipileAccountId}}');
const keywords = String(args?.keywords ?? '').trim();
const limit = Number(args?.limit ?? 10);
if (!keywords) throw new Error('linkedin_search_profile: keywords is required');

// Unipile v1 LinkedIn search (category people).
const qs = new URLSearchParams({ account_id: accountId, keywords, limit: String(limit) });
const res = await callProvider('unipile_linkedin', 'GET', `/linkedin/search?${qs.toString()}`);
const payload = res?.body ?? res;
const items = Array.isArray(payload?.items) ? payload.items : (Array.isArray(payload) ? payload : []);

const profileSlug = '{{entityProfile}}' || 'person';
let proposed = 0;
for (const p of items.slice(0, limit)) {
  const name = String(p?.name ?? [p?.first_name, p?.last_name].filter(Boolean).join(' ') ?? 'LinkedIn profile').trim() || 'LinkedIn profile';
  await propose.entity({
    profileSlug,
    title: name,
    properties: {
      headline: p?.headline ?? null,
      company: p?.current_company ?? p?.company ?? null,
      location: p?.location ?? null,
      linkedinProviderId: p?.provider_id ?? p?.id ?? null,
      publicIdentifier: p?.public_identifier ?? p?.public_id ?? null,
      profileUrl: p?.profile_url ?? null,
      source: 'unipile-linkedin'
    },
    reasoning: `LinkedIn profile matched search "${keywords}" via Unipile.`
  });
  proposed += 1;
}
return { proposed, keywords };

// Send a LinkedIn connection request via Unipile, then record a note.
// Executor wraps this body as (async function(args, context){ <code> }); use args
// directly and `return`. callProvider runs the unipile_linkedin tool through the
// dispatcher by NAME — the dispatcher resolves its credentialRef and injects the
// X-API-KEY server-side from the vault; propose.entity routes the write through
// governance. No providerRef arg needed.
const accountId = String(args?.accountId ?? '{{unipileAccountId}}');
const providerId = String(args?.providerId ?? '').trim();
const message = typeof args?.message === 'string' ? args.message : undefined;
if (!providerId) throw new Error('linkedin_send_invite: providerId (the target LinkedIn provider_id) is required');

// Unipile v1 connection-request endpoint.
const body = { account_id: accountId, provider_id: providerId };
if (message) body.message = message;
const res = await callProvider('unipile_linkedin', 'POST', '/users/invite', body);
const ok = res?.status ? res.status >= 200 && res.status < 300 : true;

await propose.entity({
  profileSlug: 'note',
  title: `LinkedIn invitation ${ok ? 'sent' : 'attempted'} -> ${providerId}`,
  properties: {
    action: 'linkedin_send_invite',
    providerId,
    message: message ?? null,
    status: res?.status ?? null,
    success: ok,
    source: 'unipile-linkedin'
  },
  reasoning: 'Recorded the outbound LinkedIn connection request for the activity timeline.'
});
return { success: ok, providerId, status: res?.status ?? null };
